 useEffect(()=>{let ok=true;(async()=>{const{count}=await supabase.from('customer_analyzer_assays').select('*',{count:'exact',head:true}).eq('analyzer_id',analyzer.id);if(ok)setCount(count||0)})();return()=>{ok=false}},[analyzer.id]);
