function BasicModule({table,title,fields}){const[rows,setRows]=useState([]),[customers,setCustomers]=useState([]),[show,setShow]=useState(false),[f,setF]=useState({customer_id:'',date:today(),product:'',priority:'Medium',status:'Open',description:'',resolution:'',participants:'',trainer:'',notes:''});useEffect(()=>{load();supabase.from('customers').select('id,customer_name').order('customer_name').then(({data})=>setCustomers(data||[]))},[]);async function load(){const{data}=await supabase.from(table).select('*,customers(customer_name)').order('created_at',{ascending:false});setRows(data||[])}async function save(e){e.preventDefault();await supabase.from(table).insert(f);setShow(false);load()}const complaint=table==='complaints';return <><DataToolbar q="" setQ={()=>{}} add={()=>setShow(true)} label={complaint?'New Complaint':'Record Training'}/><div className="card table-wrap"><table><thead><tr>{fields.map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.customers?.customer_name||'—'}</td><td>{r.date||'—'}</td><td>{r.product||'—'}</td>{complaint?<><td><Badge v={r.priority}/></td><td><Badge v={r.status}/></td><td>{r.description||'—'}</td><td>{r.resolution||'—'}</td></>:<><td>{r.participants||'—'}</td><td>{r.trainer||'—'}</td><td>{r.notes||'—'}</td></>}</tr>)}</tbody></table>{!rows.length&&<div className="empty">No records yet.</div>}</div>{show&&<SimpleModal title={complaint?'New Customer Complaint':'Record Customer Training'} close={()=>setShow(false)}><form onSubmit={save}><div className="form-grid"><label>Customer<select required value={f.customer_id} onChange={e=>setF({...f,customer_id:e.target.value})}><option value="">Select customer…</option>{customers.map(c=><option key={c.id} value={c.id}>{c.customer_name}</option>)}</select></label><label>Date<input type="date" value={f.date} onChange={e=>setF({...f,date:e.target.value})}/></label><label>Product / Assay<input value={f.product} onChange={e=>setF({...f,product:e.target.value})}/></label>{complaint?<><label>Priority<select value={f.priority} onChange={e=>setF({...f,priority:e.target.value})}><option>High</option><option>Medium</option><option>Low</option></select></label><label>Status<select value={f.status} onChange={e=>setF({...f,status:e.target.value})}><option>Open</option><option>In Progress</option><option>Resolved</option><option>Closed</option></select></label></>:<><label>Participants<input value={f.participants} onChange={e=>setF({...f,participants:e.target.value})}/></label><label>Trainer<input value={f.trainer} onChange={e=>setF({...f,trainer:e.target.value})}/></label></>}</div>{complaint?<><label>Description<textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><label>Resolution<textarea value={f.resolution} onChange={e=>setF({...f,resolution:e.target.value})}/></label></>:<label>Notes<textarea value={f.notes} onChange={e=>setF({...f,notes:e.target.value})}/></label>}<div className="modal-actions"><button type="button" className="secondary" onClick={()=>setShow(false)}>Cancel</button><button className="primary">Save</button></div></form></SimpleModal>}</>}
function Reports(){const[s,setS]=useState(null);useEffect(()=>{(async()=>{const[{data:c},{data:v},{data:o},{data:ord},{data:a},{data:p},{data:t},{data:tr},{data:co}]=await Promise.all([supabase.from('customers').select('*'),supabase.from('visits').select('*'),supabase.from('opportunities').select('*'),supabase.from('orders').select('*'),supabase.from('analyzers').select('*'),supabase.from('products').select('*'),supabase.from('tasks').select('*'),supabase.from('training_records').select('*'),supabase.from('complaints').select('*')]);setS({customers:c||[],visits:v||[],opps:o||[],orders:ord||[],analyzers:a||[],products:p||[],tasks:t||[],training:tr||[],complaints:co||[]})})()},[]);if(!s)return <div className="card empty">Loading reports…</div>;const now=new Date(),month=now.toISOString().slice(0,7),year=String(now.getFullYear()),mv=s.visits.filter(x=>x.visit_date?.startsWith(month)),mo=s.orders.filter(x=>x.order_date?.startsWith(month)),yo=s.orders.filter(x=>x.order_date?.startsWith(year)),won=s.opps.filter(x=>x.stage==='Won'),pipeline=s.opps.filter(x=>!['Won','Lost'].includes(x.stage)).reduce((n,x)=>n+Number(x.estimated_value||0),0),salesMonth=mo.reduce((n,x)=>n+Number(x.total_amount||0),0),salesYear=yo.reduce((n,x)=>n+Number(x.total_amount||0),0);return <><div className="grid stats"><div className="card stat"><span>Sales This Month</span><strong>{salesMonth.toFixed(2)} KWD</strong></div><div className="card stat"><span>Sales This Year</span><strong>{salesYear.toFixed(2)} KWD</strong></div><div className="card stat"><span>Visits This Month</span><strong>{mv.length}</strong></div><div className="card stat"><span>Open Pipeline</span><strong>{pipeline.toFixed(2)} KWD</strong></div></div><div className="grid two"><div className="card"><h2>Sales Report</h2><div className="report-list"><p><strong>Total orders:</strong> {s.orders.length}</p><p><strong>Month orders:</strong> {mo.length}</p><p><strong>Year orders:</strong> {yo.length}</p><p><strong>Total order value:</strong> {s.orders.reduce((n,x)=>n+Number(x.total_amount||0),0).toFixed(2)} KWD</p></div></div><div className="card"><h2>Field Activity</h2><div className="report-list"><p><strong>Total customers:</strong> {s.customers.length}</p><p><strong>Total visits:</strong> {s.visits.length}</p><p><strong>Active analyzers:</strong> {s.analyzers.filter(x=>x.status==='Active').length}</p><p><strong>Training records:</strong> {s.training.length}</p></div></div><div className="card"><h2>Opportunities</h2><div className="report-list"><p><strong>Open opportunities:</strong> {s.opps.filter(x=>!['Won','Lost'].includes(x.stage)).length}</p><p><strong>Won:</strong> {won.length}</p><p><strong>Pipeline:</strong> {pipeline.toFixed(2)} KWD</p><p><strong>Won value:</strong> {won.reduce((n,x)=>n+Number(x.estimated_value||0),0).toFixed(2)} KWD</p></div></div><div className="card"><h2>Service</h2><div className="report-list"><p><strong>Open tasks:</strong> {s.tasks.filter(x=>x.status!=='Completed').length}</p><p><strong>Complaints:</strong> {s.complaints.length}</p><p><strong>Open complaints:</strong> {s.complaints.filter(x=>x.status!=='Closed').length}</p><p><strong>Active products:</strong> {s.products.filter(x=>x.active).length}</p></div></div></div></>}
